// FILEDATA sub-file index invariants (issue #44). Reads the committed index
// generated by Editor/build_s4_subfile_index.py and asserts the tiling and
// alignment invariants against the numbers measured on the pristine NTSC-U
// disc. Self-skips (exit 0) when the index is absent — it is generated from
// a local disc image, so CI checkouts may not have it.
import { existsSync, readFileSync } from "fs";
import path from "path";
import { fileURLToPath } from "url";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const INDEX = path.join(HERE, "..", "..", "Editor", "s4_subfile_index.json");

if (!existsSync(INDEX)) {
  console.log("SKIP sub-file index: Editor/s4_subfile_index.json not present " +
              "(generate it with Editor/build_s4_subfile_index.py and a local disc image).");
  process.exit(0);
}

let failures = 0;
const ok = (m) => console.log("  ✓ " + m);
const bad = (m) => { console.log("  ✗ " + m); failures++; };
const align2048 = (n) => Math.floor((n + 2047) / 2048) * 2048;

const EXPECT = {
  "FILEDATA.BI2": { archives: 259, entries: 4537, endDelta: 2048, tilingPairs: 258 },
  "FILEDATA.BI1": { archives: 1066, entries: 57771, endDelta: 0, tilingPairs: 1065 },
  // BIN's archives live in 6 runs separated by other data: 1520 archives, 1514 tiling pairs
  "FILEDATA.BIN": { archives: 1520, entries: 52461, endDelta: 0, tilingPairs: 1514 },
};

const index = JSON.parse(readFileSync(INDEX, "utf-8"));
console.log("FILEDATA sub-file index:");

for (const [name, exp] of Object.entries(EXPECT)) {
  const file = index.files[name];
  if (!file) { bad(`${name} missing from index`); continue; }
  const archives = file.archives;
  const entries = archives.reduce((n, a) => n + a.entries.length, 0);
  archives.length === exp.archives
    ? ok(`${name}: ${archives.length} archives`)
    : bad(`${name}: ${archives.length} archives, expected ${exp.archives}`);
  entries === exp.entries
    ? ok(`${name}: ${entries} entries`)
    : bad(`${name}: ${entries} entries, expected ${exp.entries}`);

  let tiles = 0, unaligned = 0, badFlags = 0;
  for (let i = 0; i < archives.length; i++) {
    const a = archives[i];
    if (i + 1 < archives.length && archives[i + 1].offset === a.offset + align2048(a.total)) tiles++;
    for (const e of a.entries) {
      if (e.offset % 16 !== 0) unaligned++;
      if (![0, 2, 3].includes(e.flags)) badFlags++;
      if (e.offset + e.size > a.total) bad(`${name} archive ${i}: entry overruns archive total`);
    }
  }
  tiles === exp.tilingPairs
    ? ok(`${name}: tiling ${tiles}/${exp.tilingPairs} consecutive pairs exact`)
    : bad(`${name}: tiling ${tiles}/${exp.tilingPairs} pairs`);
  const last = archives[archives.length - 1];
  const delta = file.size - (last.offset + last.total);
  delta === exp.endDelta
    ? ok(`${name}: last archive ends with delta ${delta}`)
    : bad(`${name}: last archive end delta ${delta}, expected ${exp.endDelta}`);
  unaligned === 0 ? ok(`${name}: every entry offset 16-byte aligned`) : bad(`${name}: ${unaligned} unaligned entry offsets`);
  badFlags === 0 ? ok(`${name}: entry flags all in {0, 2, 3}`) : bad(`${name}: ${badFlags} entries with unknown flags`);
}

if (failures) { console.log(`\n${failures} sub-file index check(s) FAILED`); process.exit(1); }
console.log("\nAll sub-file index checks passed.");
